import { z } from 'zod';
import raw from '@data/thermal_kntt.json';
import { dopri5 } from '@/core/ode';
import {
  loadDataset,
  LocalizedTextSchema,
  ReviewStatusSchema,
  type Source,
} from '@/core/data/dataset';

/**
 * Vật lí 12 KNTT Chương I "Vật lí nhiệt", Bài 2–6: internal energy and the first law, temperature
 * scales, specific heat, specific latent heats of fusion and vaporisation. Every constant is the
 * textbook's (data/thermal_kntt.json, generated by scripts/data/gen_thermal_kntt.py; review
 * pending, DATA_REVIEW VL12-TH-1). The heating curve is Q = mcΔT, Q = λm, Q = Lm stage by stage,
 * with the heater's useful power H·P (the book's questions on tr. 21 and 24).
 */
const nul = z.number().nullable();
const SubstanceSchema = z.object({
  id: z.string().min(1),
  name: LocalizedTextSchema,
  c_solid: nul,
  c_liquid: nul,
  c_gas: nul,
  melt_C: nul,
  lambda: nul,
  boil_C: nul,
  L: nul,
  review_status: ReviewStatusSchema,
});
const ExtraSchema = z.object({
  reference: z.array(z.object({ kelvin: nul, celsius: nul, label: LocalizedTextSchema })),
  thermometers: z.array(
    z.object({ id: z.string(), name: LocalizedTextSchema, min_K: z.number(), max_K: z.number() }),
  ),
  examples: z.array(z.looseObject({ id: z.string(), lesson: z.number(), page: z.number() })),
  kelvin_offset: z.literal(273.15),
  kelvin_offset_rounded: z.literal(273),
});

const dataset = loadDataset('thermal_kntt', SubstanceSchema, raw);
const extra = ExtraSchema.parse(raw);

export type Substance = z.infer<typeof SubstanceSchema>;
export const SUBSTANCES: readonly Substance[] = dataset.items;
export const REFERENCE = extra.reference;
export const THERMOMETERS = extra.thermometers;
export const THERMAL_SOURCE: Source = dataset.source;
/** T (K) = t (°C) + 273,15; the book usually rounds to + 273 (tr. 17–18). */
export const K_OFFSET = extra.kelvin_offset;
export const K_OFFSET_ROUNDED = extra.kelvin_offset_rounded;

export const substance = (id: string): Substance => {
  const s = SUBSTANCES.find((x) => x.id === id);
  if (!s) throw new Error(`no substance ${id}`);
  return s;
};

/* ───────── Heating curve ───────── */

/** What can be heated: the book gives a whole heating curve only for these. */
export const PRESETS = ['ice', 'water', 'iron', 'copper', 'lead', 'mercury'] as const;
export type Preset = (typeof PRESETS)[number];

interface PresetDef {
  substance: string;
  phase: 'solid' | 'liquid';
  /** Allowed starting temperatures (°C). */
  t0: readonly [number, number];
}
const PRESET_DEFS: Record<Preset, PresetDef> = {
  ice: { substance: 'water', phase: 'solid', t0: [-40, 0] },
  water: { substance: 'water', phase: 'liquid', t0: [0, 99] },
  iron: { substance: 'iron', phase: 'solid', t0: [0, 1500] },
  copper: { substance: 'copper', phase: 'solid', t0: [0, 1080] },
  lead: { substance: 'lead', phase: 'solid', t0: [0, 320] },
  mercury: { substance: 'mercury', phase: 'liquid', t0: [0, 350] },
};
export const presetDef = (p: Preset) => PRESET_DEFS[p];

export type StageKind = 'heatSolid' | 'melt' | 'heatLiquid' | 'boil';
export interface Stage {
  kind: StageKind;
  /** Temperatures at the start and end of the stage (°C); equal for a change of state. */
  from: number;
  to: number;
  /** Heat the stage takes (J) and the time it lasts with the useful power (s). */
  Q: number;
  dt: number;
  /** Time the stage starts (s). */
  start: number;
}

export interface HeatingInput {
  preset: Preset;
  /** kg */
  m: number;
  /** °C */
  t0: number;
  /** Heater power (W) and the share of it the body takes (0–1). */
  P: number;
  eff: number;
}

/**
 * The stages from t0 to the end of the book's data: ice → water → steam at 100 °C; a metal heated to
 * its melting point and melted (the book gives no specific heat for the liquid metal); mercury
 * heated to its boiling point and boiled.
 */
export function heatingPlan(inp: HeatingInput): Stage[] {
  const def = PRESET_DEFS[inp.preset];
  const s = substance(def.substance);
  const power = inp.P * inp.eff;
  const stages: Stage[] = [];
  let start = 0;
  const push = (kind: StageKind, from: number, to: number, Q: number) => {
    const dt = Q / power;
    stages.push({ kind, from, to, Q, dt, start });
    start += dt;
  };
  let t = inp.t0;
  if (def.phase === 'solid') {
    const tm = s.melt_C ?? 0;
    push('heatSolid', t, tm, inp.m * (s.c_solid ?? 0) * (tm - t));
    push('melt', tm, tm, inp.m * (s.lambda ?? 0));
    t = tm;
    if (s.c_liquid === null || s.boil_C === null) return stages;
  }
  const tb = s.boil_C ?? 0;
  push('heatLiquid', t, tb, inp.m * (s.c_liquid ?? 0) * (tb - t));
  push('boil', tb, tb, inp.m * (s.L ?? 0));
  return stages;
}

export const totalHeat = (stages: readonly Stage[]) => stages.reduce((a, s) => a + s.Q, 0);
export const totalTime = (stages: readonly Stage[]) => stages.reduce((a, s) => a + s.dt, 0);

export interface StateAt {
  /** °C */
  t: number;
  stage: Stage;
  /** Share of the change of state done (0–1) during melt/boil; 0 otherwise. */
  done: number;
  /** Heat taken since τ = 0 (J). */
  Q: number;
}

/** Temperature and state at time τ (s) along the plan. */
export function stateAt(stages: readonly Stage[], tau: number): StateAt {
  const last = stages[stages.length - 1];
  if (!last) throw new Error('empty plan');
  const st = stages.find((s) => tau <= s.start + s.dt) ?? last;
  const u = st.dt > 0 ? Math.min(1, Math.max(0, (tau - st.start) / st.dt)) : 1;
  const before = stages.slice(0, stages.indexOf(st)).reduce((a, s) => a + s.Q, 0);
  const plateau = st.kind === 'melt' || st.kind === 'boil';
  return {
    t: plateau ? st.from : st.from + u * (st.to - st.from),
    stage: st,
    done: plateau ? u : 0,
    Q: before + u * st.Q,
  };
}

/** Targets the panel offers: a temperature in a heating stage, or the end of a change of state. */
export type Target = { kind: 'temp'; t: number } | { kind: 'melted' } | { kind: 'boiled' };

/** Heat and time to reach the target, or null when the plan never gets there. */
export function reach(
  stages: readonly Stage[],
  target: Target,
): { Q: number; time: number } | null {
  let Q = 0;
  for (const s of stages) {
    if (target.kind === 'temp' && (s.kind === 'heatSolid' || s.kind === 'heatLiquid')) {
      const lo = Math.min(s.from, s.to);
      const hi = Math.max(s.from, s.to);
      if (target.t >= lo && target.t <= hi && s.to !== s.from) {
        const share = (target.t - s.from) / (s.to - s.from);
        return { Q: Q + share * s.Q, time: s.start + share * s.dt };
      }
    }
    Q += s.Q;
    if (target.kind === 'melted' && s.kind === 'melt') return { Q, time: s.start + s.dt };
    if (target.kind === 'boiled' && s.kind === 'boil') return { Q, time: s.start + s.dt };
  }
  return null;
}

/**
 * Independent check: integrate the energy balance as an ODE with DOPRI5. State [T, x]: in a heating
 * stage dT/dτ = H·P/(m c); in a change of state dx/dτ = H·P/(m λ) (or L). Each stage ends on an
 * event (T reaches the next point, x reaches 1). Returns the stage end times found by integration.
 */
export function integratedStageEnds(inp: HeatingInput): number[] {
  const def = PRESET_DEFS[inp.preset];
  const s = substance(def.substance);
  const power = inp.P * inp.eff;
  const ends: number[] = [];
  let tau = 0;
  let T = inp.t0;
  const run = (rate: number, target: number, y0: number) => {
    if (target <= y0) {
      ends.push(tau);
      return;
    }
    const horizon = ((target - y0) / rate) * 2 + 1;
    const r = dopri5(
      (_t, _y, dy) => {
        dy[0] = rate;
      },
      [y0],
      tau,
      tau + horizon,
      {
        rtol: 1e-12,
        atol: 1e-12,
        events: [{ id: 'end', g: (_t, y) => (y[0] ?? 0) - target, direction: 1, terminal: true }],
      },
    );
    tau = r.events[0]?.t ?? r.t;
    ends.push(tau);
  };
  if (def.phase === 'solid') {
    const tm = s.melt_C ?? 0;
    run(power / (inp.m * (s.c_solid ?? 1)), tm, T);
    run(power / (inp.m * (s.lambda ?? 1)), 1, 0);
    T = tm;
    if (s.c_liquid === null || s.boil_C === null) return ends;
  }
  run(power / (inp.m * (s.c_liquid ?? 1)), s.boil_C ?? 0, T);
  run(power / (inp.m * (s.L ?? 1)), 1, 0);
  return ends;
}

/* ───────── Temperature scales (Bài 3) ───────── */

export type TempUnit = 'C' | 'K' | 'F';

/** A temperature in all three scales; kelvins both exact (+273,15) and as the book rounds (+273). */
export function convert(value: number, unit: TempUnit) {
  const c = unit === 'C' ? value : unit === 'K' ? value - K_OFFSET : (value - 32) / 1.8;
  return { C: c, K: c + K_OFFSET, Krounded: c + K_OFFSET_ROUNDED, F: 32 + 1.8 * c };
}

/** True when the value is at or above absolute zero. */
export const physical = (value: number, unit: TempUnit) => convert(value, unit).K >= -1e-9;

/* ───────── First law (Bài 2) ───────── */

/** ΔU = A + Q (A > 0: the body receives work; Q > 0: it receives heat). */
export const deltaU = (A: number, Q: number) => A + Q;

/**
 * The book's question 2 (tr. 14): a body slides from rest down an incline; with no heat exchanged
 * with the incline, the friction work turns into the body's internal energy.
 */
export function inclineExample(m: number, length: number, angleDeg: number, v: number, g: number) {
  const h = length * Math.sin((angleDeg * Math.PI) / 180);
  const friction = -(m * g * h - 0.5 * m * v * v);
  return { h, friction, dU: -friction };
}
